def choose_move(observation):
    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return clamp_move(sign(b[0] - a[0]), sign(b[1] - a[1]))

    def step_away(a, b):
        return clamp_move(sign(a[0] - b[0]), sign(a[1] - b[1]))

    def choose_nearest(start, items):
        best = None
        best_d = None
        for it in items:
            if isinstance(it, (list, tuple)) and len(it) >= 2:
                d = dist(start, (it[0], it[1]))
                if best is None or d < best_d:
                    best = (it[0], it[1])
                    best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        gw = observation.get("grid_width", 0) or 0
        gh = observation.get("grid_height", 0) or 0
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = max(corners, key=lambda c: dist(c, opp_pos))
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        best = choose_nearest(self_pos, targets)
        if best is not None:
            return step_toward(self_pos, best)
        return step_away(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("items") or []
    best = choose_nearest(self_pos, resources)
    if best is not None:
        return step_toward(self_pos, best)

    return step_toward(self_pos, opp_pos)

